array_item_probe.source:
module probe_case_array;
  typedef logic signed [1:0] s2_t;
  s2_t arr [0:0];
  s2_t one;
  logic [2:0] u;
  int r;
  initial begin
    arr[0] = 2'b11;
    one = 2'b11;
    u = 3'b111;
    case (u) inside arr: r = 1; default: r = 0; endcase
    $display("A u=111 array=%0d", r);
    case (u) inside one: r = 1; default: r = 0; endcase
    $display("A u=111 value=%0d", r);
    u = 3'b011;
    case (u) inside arr: r = 1; default: r = 0; endcase
    $display("B u=011 array=%0d", r);
    case (u) inside one: r = 1; default: r = 0; endcase
    $display("B u=011 value=%0d", r);
  end
endmodule
